    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            await JS.InvokeVoidAsync("hubGridInit", _dotNetRef, 230, 18);
        }
    }

    [JSInvokable]
    public async Task OnGridMeasured(Dictionary<string, int> counts)
    {
        _visibleCounts = counts;
        _measured = true;
        await InvokeAsync(StateHasChanged);
    }

    private int GetVisibleCount(string catId, int total)
    {
        if (!_measured) return total;
        return _visibleCounts.GetValueOrDefault(catId, total);
    }

    public async ValueTask DisposeAsync()
    {
        await JS.InvokeVoidAsync("hubGridDispose");
        _dotNetRef?.Dispose();
    }

